#!/usr/bin/env python3
"""Atomic HTTP/3-to-HTTP/1.1 bridge with a per-origin audit ledger.

Decoded HTTP/3 request events (QUIC reliability and QPACK already done) are
buffered per stream.  On FIN the complete message is validated against this
deployment's rules and, only when every rule holds, serialized as canonical
HTTP/1.1 bytes and appended to the routed origin's pipeline, so each pipeline
follows FIN order.  RESET cancels a stream, a missing terminal event leaves it
incomplete, and a rejected stream contributes no bytes at all.

Every string inside a field pair is an octet string: one Latin-1 code point per
octet (U+0000..U+00FF).  The same convention applies to the ledger.  Nothing
here opens a socket, spawns a process, contacts an origin, or writes a file.
"""

import ipaddress
import json
import sys

# ---------------------------------------------------------------------------
# Deployment limits and grammars
# ---------------------------------------------------------------------------

MAX_CONTENT = 65536   # concatenated DATA octets per stream
MAX_SECTION = 8192    # uncompressed size of a single HEADERS section

HEADERS = 0           # frame markers used by the per-stream buffers
DATA = 1

METHODS = frozenset((b"GET", b"HEAD", b"POST", b"PUT",
                     b"PATCH", b"DELETE", b"OPTIONS"))
SCHEMES = frozenset((b"http", b"https"))
DEFAULT_PORTS = {b"http": 80, b"https": 443}

# Connection/framing concerns plus deployment exclusions; rejected even empty.
PROHIBITED_FIELDS = frozenset((
    b"connection", b"proxy-connection", b"keep-alive", b"transfer-encoding",
    b"upgrade", b"http2-settings", b"trailer"))

# Regular initial fields that may repeat without merging.
LIST_FIELDS = frozenset((
    b"accept", b"accept-encoding", b"cache-control", b"if-match",
    b"if-none-match", b"pragma", b"vary"))

PSEUDO_HEADERS = frozenset((b":method", b":scheme", b":authority", b":path"))

# Octets permitted in a regular field name (lower-case token grammar only).
_NAME_ALLOWED = b"abcdefghijklmnopqrstuvwxyz0123456789!#$%&'*+-.^_`|~"

# Octets permitted anywhere in a field value.  SP and HTAB are interior-only
# and are refused at the edges separately.
_VALUE_ALLOWED = bytes([0x09, 0x20] + list(range(0x21, 0x7F))
                       + list(range(0x80, 0x100)))

# Octets permitted in an origin-form path; '%' is validated as an escape.
_PATH_ALLOWED = (b"ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                 b"abcdefghijklmnopqrstuvwxyz0123456789-._~!$&'()*+,;=:@/?%")

_DIGITS = b"0123456789"
_HEX = frozenset(b"0123456789abcdefABCDEF")
_X_LIST = b"x-list-"
_X_AUDIT = b"x-audit-"


# ---------------------------------------------------------------------------
# Octet helpers
# ---------------------------------------------------------------------------

def octets(text):
    """Return the octet string for a Latin-1 code-point string, else None."""
    if isinstance(text, str):
        try:
            return text.encode("latin-1")
        except UnicodeEncodeError:
            return None
    return None


def field_name_ok(name):
    """Non-empty lower-case token."""
    return bool(name) and not name.translate(None, _NAME_ALLOWED)


def field_value_ok(value):
    """Field-value octet rule: SP/HTAB only in the interior."""
    if not value:
        return True
    for edge in (value[0], value[-1]):
        if not (0x21 <= edge <= 0x7E or edge >= 0x80):
            return False
    return not value.translate(None, _VALUE_ALLOWED)


def path_ok(path, method):
    """'*' for OPTIONS, else an origin-form target preserved exactly."""
    if path == b"*":
        return method == b"OPTIONS"
    if not path or path[0] != 0x2F or path[1:2] == b"/":
        return False
    if path.translate(None, _PATH_ALLOWED):
        return False
    pos = path.find(b"%")
    while pos != -1:
        if (pos + 3 > len(path) or path[pos + 1] not in _HEX
                or path[pos + 2] not in _HEX):
            return False
        pos = path.find(b"%", pos + 1)
    return True


# ---------------------------------------------------------------------------
# Authority grammar, normalization and routing identity
# ---------------------------------------------------------------------------

def _alphanum(byte):
    return (0x30 <= byte <= 0x39 or 0x41 <= byte <= 0x5A
            or 0x61 <= byte <= 0x7A)


def parse_port(text):
    """Port of 1..5 ASCII decimal digits denoting 1..65535, else None."""
    if not 1 <= len(text) <= 5:
        return None
    if text.translate(None, _DIGITS):
        return None
    value = int(text)
    if 1 <= value <= 65535:
        return value
    return None


def canonical_host(host):
    """Canonicalize a DNS name or IPv4 literal; None when invalid."""
    if not 1 <= len(host) <= 253:
        return None
    labels = host.split(b".")
    # A name of exactly four all-digit labels must be an IPv4 literal.
    if len(labels) == 4 and all(
            label and not label.translate(None, _DIGITS) for label in labels):
        parts = []
        for label in labels:
            if len(label) > 1 and label[0] == 0x30:
                return None            # leading zero
            value = int(label)
            if value > 255:
                return None
            parts.append(b"%d" % value)
        return b".".join(parts)
    for label in labels:
        if not 1 <= len(label) <= 63:
            return None
        if not (_alphanum(label[0]) and _alphanum(label[-1])):
            return None
        for byte in label:
            if not (_alphanum(byte) or byte == 0x2D):
                return None
    return host.lower()


def canonical_authority(authority, scheme):
    """Return the canonical authority octets, or None when invalid."""
    if not authority:
        return None
    port = None
    if authority[0] == 0x5B:                      # '['
        end = authority.find(b"]")
        if end == -1:
            return None
        host = authority[1:end]
        rest = authority[end + 1:]
        if rest:
            if rest[0] != 0x3A:                   # ':'
                return None
            port = parse_port(rest[1:])
            if port is None:
                return None
        if b"%" in host:                          # no zone identifier
            return None
        try:
            address = ipaddress.IPv6Address(host.decode("ascii"))
        except ValueError:
            return None
        canonical = b"[" + address.compressed.encode("ascii") + b"]"
    else:
        if b":" in authority:
            host, _, port_text = authority.partition(b":")
            port = parse_port(port_text)
            if port is None:
                return None
        else:
            host = authority
        canonical = canonical_host(host)
        if canonical is None:
            return None
    if port is not None and port != DEFAULT_PORTS[scheme]:
        canonical += b":%d" % port
    return canonical


# ---------------------------------------------------------------------------
# Per-stream validation and canonical HTTP/1.1 serialization
# ---------------------------------------------------------------------------

def finalize(frames, routes):
    """Validate one FIN-terminated stream.

    Returns (request_bytes, cache_key, origin_label) on success and None when
    any rule fails.  ``frames`` holds (HEADERS, fields) / (DATA, bytes) pairs
    with unknown frames already dropped.
    """
    # ---- frame structure: one HEADERS, DATA*, optional trailing HEADERS ----
    if not frames or frames[0][0] != HEADERS:
        return None
    initial = frames[0][1]
    index = 1
    total = len(frames)
    chunks = []
    while index < total and frames[index][0] == DATA:
        chunks.append(frames[index][1])
        index += 1
    trailing = None
    if index < total:
        if frames[index][0] != HEADERS or index + 1 != total:
            return None
        trailing = frames[index][1]
    content = b"".join(chunks)
    if len(content) > MAX_CONTENT:
        return None

    # ---- initial HEADERS: pseudo-headers first, then regular fields ----
    pseudo = {}
    regular = []
    size = 0
    for pair in initial:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            return None
        name = octets(pair[0])
        value = octets(pair[1])
        if name is None or value is None:
            return None
        size += len(name) + len(value) + 32
        if name[0:1] == b":":
            if regular:
                return None                      # pseudo after regular field
            if name not in PSEUDO_HEADERS or name in pseudo:
                return None
            if not field_value_ok(value):
                return None
            pseudo[name] = value
        else:
            if not field_name_ok(name) or not field_value_ok(value):
                return None
            regular.append((name, value))
    if size > MAX_SECTION:
        return None

    method = pseudo.get(b":method")
    scheme = pseudo.get(b":scheme")
    path = pseudo.get(b":path")
    authority = pseudo.get(b":authority")
    if method is None or scheme is None or path is None:
        return None
    if method not in METHODS or scheme not in SCHEMES:
        return None
    if not path_ok(path, method):
        return None

    # ---- regular field policy: duplicates, exclusions, content-length ----
    seen = set()
    length_lines = []
    cookies = []
    host_value = None
    te_seen = False
    for name, value in regular:
        if name in PROHIBITED_FIELDS:
            return None
        if name == b"host":
            if host_value is not None:
                return None                      # repeated host
            host_value = value
        elif name == b"te":
            if te_seen:
                return None
            te_seen = True
            if value != b"trailers":
                return None
        elif name == b"content-length":
            length_lines.append(value)
        elif name == b"cookie":
            cookies.append(value)
        elif (name in LIST_FIELDS
              or (len(name) > len(_X_LIST) and name.startswith(_X_LIST))):
            continue                             # repeatable list field
        elif name in seen:
            return None                          # repeated singleton
        else:
            seen.add(name)

    # Content-Length: comma-separated members, all one integer, equal to body.
    if length_lines:
        expected = b"%d" % len(content)
        reference = None
        for line in length_lines:
            for member in line.split(b","):
                item = member.strip(b" \t")
                if not item or item.translate(None, _DIGITS):
                    return None
                trimmed = item.lstrip(b"0") or b"0"
                if reference is None:
                    reference = trimmed
                elif reference != trimmed:
                    return None
        if reference != expected:
            return None

    # ---- request authority: :authority with an exactly matching host ----
    if authority is not None and host_value is not None:
        if authority != host_value:
            return None
        target = authority
    elif authority is not None:
        target = authority
    elif host_value is not None:
        target = host_value
    else:
        return None
    if not target:
        return None
    canonical = canonical_authority(target, scheme)
    if canonical is None:
        return None
    origin = routes.get((scheme + b"://" + canonical).decode("latin-1"))
    if origin is None:
        return None

    # ---- trailing HEADERS: repeatable x-audit-* list fields only ----
    trailer_pairs = []
    if trailing is not None:
        size = 0
        for pair in trailing:
            if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                return None
            name = octets(pair[0])
            value = octets(pair[1])
            if name is None or value is None:
                return None
            size += len(name) + len(value) + 32
            if (len(name) <= len(_X_AUDIT) or not name.startswith(_X_AUDIT)
                    or not field_name_ok(name)):
                return None
            if not field_value_ok(value):
                return None
            trailer_pairs.append((name, value))
        if size > MAX_SECTION:
            return None

    # ---- canonical HTTP/1.1 bytes ----
    request = bytearray()
    request += method
    request += b" "
    request += path
    request += b" HTTP/1.1\r\n"
    request += b"host: "
    request += canonical
    request += b"\r\n"
    cookie_blob = b"; ".join(cookies)
    cookie_placed = not cookies
    for name, value in regular:
        if name == b"cookie":
            if not cookie_placed:                # one joined line, first spot
                cookie_placed = True
                request += b"cookie: "
                request += cookie_blob
                request += b"\r\n"
        elif name == b"host" or name == b"content-length" or name == b"te":
            continue                             # consumed by the bridge
        else:
            request += name
            request += b": "
            request += value
            request += b"\r\n"
    if trailing is None:
        request += b"content-length: %d\r\n\r\n" % len(content)
        request += content
    else:
        request += b"transfer-encoding: chunked\r\n"
        if trailer_pairs:
            announced = []
            announced_seen = set()
            for name, _value in trailer_pairs:
                if name not in announced_seen:
                    announced_seen.add(name)
                    announced.append(name)
            request += b"trailer: "
            request += b", ".join(announced)
            request += b"\r\n"
        request += b"\r\n"
        if content:                              # one chunk, exact segmentation
            request += b"%x\r\n" % len(content)
            request += content
            request += b"\r\n"
        request += b"0\r\n"
        for name, value in trailer_pairs:
            request += name
            request += b": "
            request += value
            request += b"\r\n"
        request += b"\r\n"

    cache_key = [method.decode("latin-1"), scheme.decode("latin-1"),
                 canonical.decode("latin-1"), path.decode("latin-1")]
    return bytes(request), cache_key, origin


# ---------------------------------------------------------------------------
# Scenario driver
# ---------------------------------------------------------------------------

def bridge(scenario):
    routes = scenario["routes"]
    events = scenario["events"]

    # Every distinct origin label gets a pipeline, used or not.
    pipelines = {}
    for label in routes.values():
        if label not in pipelines:
            pipelines[label] = bytearray()

    # Buffer each observed stream, including one first seen in a terminal,
    # DATA or unknown frame.  Unknown frames contribute nothing anywhere.
    streams = {}
    for index, event in enumerate(events):
        sid = event["sid"]
        kind = event["type"]
        state = streams.get(sid)
        if state is None:
            state = streams[sid] = [[], None, None]
        if kind == "headers":
            state[0].append((HEADERS, event["fields"]))
        elif kind == "data":
            state[0].append((DATA, bytes.fromhex(event["hex"])))
        elif kind == "fin":
            state[1] = "fin"
            state[2] = index
        elif kind == "reset":
            state[1] = "reset"
            state[2] = index

    records = []
    for sid in sorted(streams):
        frames, terminal, at = streams[sid]
        record = {"sid": sid, "status": "incomplete", "commit_at": None,
                  "origin": None, "offset": None, "length": 0,
                  "cache_key": None}
        if terminal == "reset":
            record["status"] = "cancelled"       # contents never matter
        elif terminal == "fin":
            outcome = finalize(frames, routes)
            if outcome is None:
                record["status"] = "rejected"    # atomic: no bytes at all
            else:
                request, cache_key, origin = outcome
                pipeline = pipelines[origin]
                record["status"] = "forwarded"
                record["commit_at"] = at
                record["origin"] = origin
                record["offset"] = len(pipeline)
                record["length"] = len(request)
                record["cache_key"] = cache_key
                pipeline += request
        records.append(record)

    return {"streams": records,
            "origins": {label: pipeline.hex()
                        for label, pipeline in pipelines.items()}}


def main():
    scenario = json.load(sys.stdin)
    sys.stdout.write(json.dumps(bridge(scenario), ensure_ascii=True))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
